-- HALO: check that migration 0033 is applied correctly. Read only.
-- Generated by scripts/build-apply-bundle.mjs from each migration's own verification query.
-- Expect one row: all_migrations_ok = true and failing = none.

with checks as (
  select '0033' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        (select bool_and(relrowsecurity) from pg_class
          where oid in ('public.public_evidence_snapshots'::regclass, 'public.public_evidence_runs'::regclass)) as rls_on,
        (select count(*) from pg_policies
          where schemaname = 'public' and tablename in ('public_evidence_snapshots', 'public_evidence_runs')) = 0
          as no_policies,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           cross join unnest(array['public.public_evidence_snapshots', 'public.public_evidence_runs']) as t
           where has_any_column_privilege(r, t, 'SELECT')
              or has_any_column_privilege(r, t, 'INSERT')
              or has_any_column_privilege(r, t, 'UPDATE')
              or has_table_privilege(r, t, 'DELETE')
              or has_table_privilege(r, t, 'TRUNCATE'))
          as no_client_access,
        not has_function_privilege('anon', 'public.record_public_evidence_run(jsonb)', 'EXECUTE')
          and not has_function_privilege('authenticated', 'public.record_public_evidence_run(jsonb)', 'EXECUTE')
          and has_function_privilege('service_role', 'public.record_public_evidence_run(jsonb)', 'EXECUTE')
          as function_service_role_only,
        (select count(*) from pg_constraint
          where conrelid in ('public.public_evidence_snapshots'::regclass, 'public.public_evidence_runs'::regclass)
            and contype = 'c') = 8
          as eight_checks
  ) q, jsonb_each_text(to_jsonb(q)) j
)
select bool_and(ok) as all_migrations_ok,
       count(*) as checks_run,
       coalesce(string_agg(migration || '.' || check_name, ', ') filter (where not ok), 'none') as failing
from checks;
